{"file_path":"src/simulate.js","content":"/**
 * The limiter itself. It runs the event log of a program through the policies
 * its routes name and yields one verdict per event.
 */

/**
 * The state a token bucket keeps for one key. Tokens are counted in units of
 * one `per`th of a token, so that partial periods accumulate exactly.
 */
function newBucketState(policy, tick) {
  return { units: policy.capacity * policy.per, last: tick }
}

/** The state a sliding window keeps for one key: the ticks it remembers. */
function newWindowState() {
  return { ticks: [], first: 0 }
}

/** Advances the state a policy keeps for a key up to the event's tick. */
function advance(policy, state, tick) {
  if (policy.kind === 'bucket') {
    const elapsed = tick - state.last
    if (elapsed > 0n) {
      const ceiling = policy.capacity * policy.per
      state.units += policy.refill * elapsed
      if (state.units > ceiling) state.units = ceiling
    }
    state.last = tick
    return
  }
  const horizon = tick - policy.span
  while (state.first < state.ticks.length && state.ticks[state.first] <= horizon) {
    state.first += 1
  }
  if (state.first > 0) {
    state.ticks = state.ticks.slice(state.first)
    state.first = 0
  }
}

/** True when the policy would let a request through in its current state. */
function allows(policy, state) {
  if (policy.kind === 'bucket') return state.units >= policy.per
  return BigInt(state.ticks.length) < policy.limit
}

/** Charges the policy for a request that every policy on the route allowed. */
function record(policy, state, tick) {
  if (policy.kind === 'bucket') {
    state.units -= policy.per
    return
  }
  state.ticks.push(tick)
}

/** The states a policy keeps, one per key it has seen. */
function stateFor(states, policy, key, tick) {
  let byKey = states.get(policy)
  if (byKey === undefined) {
    byKey = new Map()
    states.set(policy, byKey)
  }
  let state = byKey.get(key)
  if (state === undefined) {
    state = policy.kind === 'bucket' ? newBucketState(policy, tick) : newWindowState()
    byKey.set(key, state)
  }
  return state
}

/** The policies of the longest route prefix the key starts with, if any. */
function routeFor(routes, key) {
  let best = null
  for (const route of routes) {
    if (!key.startsWith(route.prefix)) continue
    if (best === null || route.prefix.length > best.prefix.length) best = route
  }
  return best === null ? [] : best.policies
}

/**
 * One verdict per event, in log order: `{ tick, key, allowed, denier }`, where
 * the denier is the first policy on the route that refused.
 */
export function simulate(program) {
  const states = new Map()
  const verdicts = []
  for (const event of program.events) {
    const policies = routeFor(program.routes, event.key)
    const pairs = policies.map((policy) => [policy, stateFor(states, policy, event.key, event.tick)])
    for (const [policy, state] of pairs) advance(policy, state, event.tick)
    let denier = null
    for (const [policy, state] of pairs) {
      if (!allows(policy, state)) {
        denier = policy
        break
      }
    }
    if (denier === null) {
      for (const [policy, state] of pairs) record(policy, state, event.tick)
    }
    verdicts.push({ tick: event.tick, key: event.key, allowed: denier === null, denier })
  }
  return verdicts
}
