/** One line per event: `<tick> <key> allow` or `<tick> <key> deny <policy>`. */
export function replayReport(verdicts) {
  let text = ''
  for (const verdict of verdicts) {
    text += verdict.allowed
      ? `${verdict.tick} ${verdict.key} allow\n`
      : `${verdict.tick} ${verdict.key} deny ${verdict.denier.name}\n`
  }
  return text
}

/** The verdicts totalled per key in ascending key order, and then overall. */
export function summaryReport(verdicts) {
  const counts = new Map()
  let allowed = 0
  let denied = 0
  for (const verdict of verdicts) {
    let count = counts.get(verdict.key)
    if (count === undefined) {
      count = { allowed: 0, denied: 0 }
      counts.set(verdict.key, count)
    }
    if (verdict.allowed) {
      count.allowed += 1
      allowed += 1
    } else {
      count.denied += 1
      denied += 1
    }
  }
  let text = ''
  for (const key of [...counts.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))) {
    const count = counts.get(key)
    text += `${key} allowed=${count.allowed} denied=${count.denied}\n`
  }
  return `${text}total allowed=${allowed} denied=${denied}\n`
}
"}

