 * The command. `node src/cli.js replay` verdicts every event of the limiter
 * file read from standard input, and `node src/cli.js summary` totals the
 * verdicts per key.
 */

import { readFileSync } from 'node:fs'
import { ParseError, parseProgram } from './parse.js'
import { simulate } from './simulate.js'
import { replayReport, summaryReport } from './report.js'

/** Reports a failure on standard error, having written nothing to output. */
function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exitCode = 2
}

function main(argv) {
  const mode = argv.length === 1 ? argv[0] : null
  if (mode !== 'replay' && mode !== 'summary') {
    fail('usage: cli.js replay|summary')
    return
  }

  let text = ''
  try {
    text = readFileSync(0, 'utf8')
  } catch {
    text = ''
  }

  let program
  try {
    program = parseProgram(text)
  } catch (error) {
    if (error instanceof ParseError) {
      fail(error.message)
      return
    }
    throw error
  }

  const verdicts = simulate(program)
  process.stdout.write(mode === 'replay' ? replayReport(verdicts) : summaryReport(verdicts))
  process.exitCode = 0
}

main(process.argv.slice(2))
"}

